function app_config(?string $path=null,$default=null){global $APP_CONFIG;if($path===null||$path==='')return$APP_CONFIG;$v=$APP_CONFIG;foreach(explode('.',$path)as$s){if(is_array($v)&&array_key_exists($s,$v))$v=$v[$s];else return$default;}return$v;}
